async fn can_parallel_dispatch(
    &self,
    tool_calls: &[NativeToolCall],
    canonical: &[String],
    claims: &[crate::tools::concurrency::ConcurrencyClaim],
) -> bool {
    let Some(par_n) = self.deps.parallel_tool_concurrency else { return false; };
    if par_n < 2 || tool_calls.len() < 2 { return false; }
    let mut seen = std::collections::HashSet::new();
    for (call, canon) in tool_calls.iter().zip(canonical) {
        if !seen.insert((call.name.as_str(), canon.as_str())) { return false; }
    }
    crate::tools::concurrency::batch_parallelizable(claims)
}

